-- 1172: Blog post - "Where It Started: Our First Hydroponics Class in 2014,
--       With the Late Dr Mallick"
--
--       Sixth post for WSQ - Basic Urban Farming with Hydroponics (TGS-2025053916),
--       and the earliest by date. An anniversary / tribute piece for the FIRST run of
--       the course on 8 Mar 2014 at Toh Orchid Farm, taught by the late Dr Mallick.
--       Cross-links to the other five hydroponics posts.
--       Ships already published (status 1); linkedin_urn carries the manual-skip
--       sentinel (back-dated post - standing rule, see the blog-pipeline skill).
--       published_at pinned to 2014-03-08.
--
-- TONE: Dr Mallick is deceased, so this is written as a respectful tribute, not as
-- marketing that leans on his name. He is referred to as "the late Dr Mallick" and
-- the claims about him are limited to what the photographs actually show: he taught
-- this class, he taught from the "Hydroponic Principle" slide, and he demonstrated
-- hands-on. His full name appears on the slide in one photo as "Dr Mallick F.
-- Rahman", but the admin refers to him as Dr Mallick, so that is what the copy uses.
-- No biography, credentials or dates of birth/death are asserted - we do not have
-- them, and inventing them for a real deceased person would be indefensible.
--
-- Every course figure was read off the LIVE course page on 2026-08-29: $350 before
-- GST, GST $31.50 (9%), nett $206.50 / $136.50, 1 day / 8 hrs at MEOD Farm, funding
-- valid 24 Mar 2025 - 23 Mar 2027, TSC AGR-FOP-2002-1.1.
--
-- VENUE: the 2014 class was at Toh Orchid Farm. The copy says so in the past tense
-- and states MEOD Farm as the CURRENT venue - today's venue is not retro-fitted.
--
-- Photographs: 7 selected from a 21-shot album supplied by the academy. These are
-- 960px-native 2014 Facebook exports averaging only 57KB, already well under the
-- <150KB compression target, so they are uploaded AS-IS - re-encoding would only
-- destroy quality for no saving (see the "never upscale / judge by bytes" rule).
-- Total 399KB. All verified HTTP 200. Under blog/hydroponics/2014-03-08-*.
--
-- NOTE on the photo NOT used: one album frame shows a tall commercial vertical farm,
-- but it is a PROJECTED SLIDE, not the venue - captioning it as Toh Orchid Farm
-- would have been wrong, so it was excluded.
--
-- Notes for future editors:
--  * apply.php splits statements on ";" at end-of-line - the content HTML is ONE line.
--  * Content is pure ASCII; excerpt uses a REAL em-dash via CHAR() (see 1161);
--    meta_description carries NO em-dash entity (see 1164).
--  * FAQ ships as native <details> accordions per the blog-pipeline rules.
--  * Idempotent: WHERE NOT EXISTS on url_key, INSERT IGNORE on tag links.
--  * SG-only guard via @mms_instance.
--  * hero_image_url is NOT set here - generated on prod post-deploy (farming theme).

SET @is_sg := IF(@mms_instance = 'SG', 1, 0);


INSERT INTO `mmd_blog_post` (`title`, `url_key`, `excerpt`, `content`, `author`, `status`, `published_at`, `related_skus`, `source_sku`, `meta_title`, `meta_description`, `meta_keywords`, `linkedin_urn`, `created_at`, `updated_at`) SELECT 'Where It Started: Our First Hydroponics Class in 2014, With the Late Dr Mallick', 'hydroponics-first-class-2014-dr-mallick', CONCAT('On 8 March 2014 we ran our first hydroponics class at Toh Orchid Farm, taught by the late Dr Mallick ', CHAR(0xE2,0x80,0x94 USING utf8mb4), ' a pioneer of hydroponics in Singapore. Eleven years and hundreds of learners later, the lesson he opened with is still the one the course is built on.'), '<p>Every course has a first run. Ours was on <strong>8 March 2014</strong>, in a room at <strong>Toh Orchid Farm</strong>, and it was taught by the late <strong>Dr Mallick</strong> &mdash; one of the people who did the early work of making hydroponics comprehensible to ordinary Singaporeans rather than only to agronomists.</p> <figure class="mmd-blog-figure"> <img src="https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/hydroponics/2014-03-08-class-with-dr-mallick.jpg" alt="The 8 March 2014 hydroponics class posing together, with Dr Mallick in a maroon shirt at the centre and completed hydroponic starter kits on the table in front" /> <figcaption>Our first hydroponics class, 8 March 2014 at Toh Orchid Farm, with Dr Mallick at the centre and the day''s finished kits on the table. Photo: Tertiary Infotech Academy.</figcaption> </figure> <p>This post is partly an anniversary note and partly a thank-you. Almost everything that is still in the syllabus &mdash; the order of the lessons, the insistence on building a working system in the room, the refusal to let anyone leave without touching a seedling &mdash; traces back to how he taught it that day.</p> <h2>The lesson he opened with</h2> <figure class="mmd-blog-figure"> <img src="https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/hydroponics/2014-03-08-hydroponic-principle-slide.jpg" alt="Dr Mallick teaching in front of a projected slide headed Hydroponic Principle, explaining that naturally occurring mineral nutrients are purified and recycled as a nutrient source for growing plants" /> <figcaption>The slide he started from: hydroponics recycles the same naturally occurring mineral nutrients plants would otherwise draw from soil. Photo: Tertiary Infotech Academy.</figcaption> </figure> <p>Read the slide. It is doing something careful.</p> <p>In 2014, the most common objection to hydroponics was that it was somehow artificial &mdash; chemicals in water, as against honest dirt. Rather than argue, he reframed: the <em>naturally occurring</em> mineral nutrients plants normally take from soil are simply purified and recycled as a nutrient solution. Same elements, different delivery. The plant cannot tell the difference because there is no difference to tell.</p> <p>Everything else in the course follows from that one idea. If soil is a delivery mechanism rather than the nutrition itself, then replacing it is an engineering problem, not a violation of anything. Eleven years on, we still open the class with the same point, and it still does the same work.</p> <figure class="mmd-blog-figure"> <img src="https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/hydroponics/2014-03-08-dr-mallick-teaching.jpg" alt="Portrait of Dr Mallick speaking to the class in front of a projected slide about mineral nutrients being purified into a nutrient solution" /> <figcaption>Dr Mallick teaching the nutrient-solution section, 8 March 2014. Photo: Tertiary Infotech Academy.</figcaption> </figure> <h2>He would not let it stay theoretical</h2> <figure class="mmd-blog-figure"> <img src="https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/hydroponics/2014-03-08-dr-mallick-demonstrating.jpg" alt="Dr Mallick leaning over a table, hands working on a hydroponic seedling tray, while learners crowd in closely to watch" /> <figcaption>The part everyone remembers: hands in the tray, learners leaning in. Photo: Tertiary Infotech Academy.</figcaption> </figure> <p>Look at how close the learners are standing. That is the actual teaching method, and it is the reason the course still runs the way it does.</p> <p>He would explain something at the projector for a few minutes, then walk to a table and do it &mdash; seat a seedling in a net pot, show what a properly soaked medium feels like, point out the root that had already found the water. The lecture existed to make the demonstration legible, never the other way round.</p> <figure class="mmd-blog-figure"> <img src="https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/hydroponics/2014-03-08-learners-building-kits.jpg" alt="Learners standing around a long table, each with a black hydroponic grow tray in front of them, assembling their own starter systems" /> <figcaption>Everyone builds their own. The 2014 class assembling starter systems &mdash; still how the course works today. Photo: Tertiary Infotech Academy.</figcaption> </figure> <p>And then everyone built their own. Not a demonstration to watch, a tray each. That one decision is why people leave able to actually start, and it survived every revision of the course since.</p> <h2>Toh Orchid Farm</h2> <figure class="mmd-blog-figure"> <img src="https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/hydroponics/2014-03-08-vertical-hydroponic-rack.jpg" alt="A tall vertical hydroponic rack holding tiers of light green leafy plants inside the open working shed at Toh Orchid Farm" /> <figcaption>A vertical growing rack in the farm''s working shed &mdash; the same tiered idea now seen in commercial vertical farms across Singapore. Photo: Tertiary Infotech Academy.</figcaption> </figure> <p>Holding the class on a working farm was deliberate. Learners walked out of the classroom and straight into a shed where plants were actually being grown and packed, and that stacked rack made the land argument without anyone needing to state it: the footprint of a cupboard, the growing area of a small plot.</p> <figure class="mmd-blog-figure"> <img src="https://pub-77c0dec029944b0386e40673ce81081f.r2.dev/blog/hydroponics/2014-03-08-toh-orchid-farm-work-area.jpg" alt="The open working and packing area at Toh Orchid Farm, with long wooden benches, trays and staff working at the far end" /> <figcaption>The working area at Toh Orchid Farm, where the 2014 class was held. Photo: Tertiary Infotech Academy.</figcaption> </figure> <p>Singapore''s growing scene looked very different then. The "30 by 30" goal had not been announced, commercial vertical farms were mostly a proposition rather than a sector, and a hydroponics class was a curiosity. What has changed since is the scale and the seriousness &mdash; not the principles, which is precisely the point of looking back at this.</p> <h2>What carried forward</h2> <p>Comparing that first run with the course as it stands today, four things came straight through:</p> <ol> <li><strong>Lead with the principle, not the equipment.</strong> Once someone understands that roots absorb nutrients as ions in water, every system type becomes a variation rather than a new thing to memorise.</li> <li><strong>Everyone builds one.</strong> A kit per learner, assembled in the room. Watching is not learning.</li> <li><strong>Teach on a working farm.</strong> Theory in the morning, production reality in the afternoon, so the ideas have somewhere to land.</li> <li><strong>Answer the "is it natural" question head-on.</strong> It is still the most common question, and it still deserves the careful answer he gave rather than a dismissive one.</li> </ol> <p>The current <a href="https://www.tertiarycourses.com.sg/wsq-basic-urban-farming-with-hydroponics.html">WSQ - Basic Urban Farming with Hydroponics</a> course has WSQ accreditation, an assessment, a Skills Framework mapping and funding that did not exist in 2014. Underneath the paperwork, it is recognisably the same class.</p> <h2>The course today</h2> <p><a href="https://www.tertiarycourses.com.sg/wsq-basic-urban-farming-with-hydroponics.html">WSQ - Basic Urban Farming with Hydroponics</a> (course code TGS-2025053916) is a <strong>1-day, 8-hour</strong> class at Beginner level with a 1-hour assessment, held at <strong>MEOD Farm, 13 Neo Tiew Harvest Lane</strong>. It maps to the SkillsFuture Skills Framework TSC <strong>Urban Farming Implementation and Management Control (AGR-FOP-2002-1.1)</strong>, with two learning outcomes:</p> <ol> <li>Perform farming activities and equipment operations according to standard operating procedures</li> <li>Execute farming operations work in accordance with regulations, WSH practices and housekeeping rules</li> </ol> <p>The day covers hydroponic system types, growing media, plant nutrition and nutrient solutions, pH and EC monitoring, indoor farming conditions, Singapore''s urban farming regulations, good agriculture practices and workplace safety &mdash; plus hands-on practice with a hydroponics kit and a guided tour of a commercial hydroponics farm.</p> <h3>What it costs</h3> <p>The full fee is <strong>$350</strong> before GST. With WSQ funding:</p> <table> <tr><th>Who you are</th><th>Nett fee</th><th>Funding</th></tr> <tr><td>Singapore Citizen / PR, aged 21 and above</td><td><strong>$206.50</strong></td><td>50% course-fee funding</td></tr> <tr><td>Singapore Citizen aged 40 and above (MCES), or SME-sponsored</td><td><strong>$136.50</strong></td><td>70% course-fee funding</td></tr> </table> <p>GST of $31.50 (9%) applies to the full course fee. Funding is valid <strong>from 24 March 2025 to 23 March 2027</strong>. Eligible Singapore Citizens can apply <strong>SkillsFuture Credit</strong> and <strong>PSEA</strong> against the nett fee, NTUC members may claim <strong>UTAP</strong>, and employers can tap <strong>SFEC</strong> with <strong>Absentee Payroll</strong> support. Completion &mdash; at least 75% attendance plus a pass in the assessment &mdash; earns a Certificate of Achievement from Tertiary Infotech Academy and an <strong>OpenCert (Statement of Achievement) from SkillsFuture Singapore</strong>.</p> <p><a href="https://www.tertiarycourses.com.sg/wsq-basic-urban-farming-with-hydroponics.html"><strong>Check the next class date and funding eligibility &rarr;</strong></a></p> <h2>Frequently asked questions</h2> <div class="mmd-faq"> <details class="mmd-faq-item"> <summary class="mmd-faq-q">Is hydroponics natural, or is it just chemicals in water?</summary> <div class="mmd-faq-a"><p>It is the same question Dr Mallick answered in 2014, and the answer has not changed. The nutrients are the naturally occurring mineral elements plants would otherwise take up from soil, purified and dissolved in water so roots can absorb them directly. Plants take three elements from air and water and thirteen as minerals, whichever way you grow them.</p></div> </details> <details class="mmd-faq-item"> <summary class="mmd-faq-q">How has the course changed since 2014?</summary> <div class="mmd-faq-a"><p>It is now WSQ-accredited with a formal assessment, mapped to a Skills Framework competency, and eligible for WSQ funding, SkillsFuture Credit, PSEA and UTAP &mdash; none of which applied in 2014. The teaching structure is largely unchanged: principle first, a kit per learner, and a working farm as the venue.</p></div> </details> <details class="mmd-faq-item"> <summary class="mmd-faq-q">Do I still build my own system in class?</summary> <div class="mmd-faq-a"><p>Yes. Hands-on practice with a hydroponics kit is part of the day, exactly as it was in 2014. Watching someone else assemble a system teaches you very little; doing it yourself is what makes the sequence stick.</p></div> </details> <details class="mmd-faq-item"> <summary class="mmd-faq-q">Where is the class held now?</summary> <div class="mmd-faq-a"><p>At MEOD Farm, 13 Neo Tiew Harvest Lane, Singapore 719838. The 2014 class was at Toh Orchid Farm; the venue has changed over the years but the principle of teaching on a working farm has not.</p></div> </details> <details class="mmd-faq-item"> <summary class="mmd-faq-q">Do I need any background to join?</summary> <div class="mmd-faq-a"><p>None. The course is Beginner level and assumes no farming or science background. Hydroponics rewards careful measurement more than a green thumb.</p></div> </details> </div> <h2>Where to go next</h2> <p>Eleven years on, the reason to learn this is stronger than it was in 2014: Singapore still imports the large majority of its food, and the people who can run these systems are the capability behind every local farm.</p> <ol> <li>Start with leafy greens and herbs &mdash; fast, forgiving, and honest about your mistakes within weeks.</li> <li>Join the next <a href="https://www.tertiarycourses.com.sg/wsq-basic-urban-farming-with-hydroponics.html"><strong>WSQ - Basic Urban Farming with Hydroponics</strong></a> class &mdash; from <strong>$136.50 nett</strong> for eligible Singapore Citizens aged 40 and above.</li> <li>Build your own system in the room, then keep it alive through one full crop cycle. That is the whole apprenticeship.</li> </ol> <p>More from this course: <a href="https://www.tertiarycourses.com.sg/blog/urban-farming-with-hydroponics-guide">how hydroponics works</a>, <a href="https://www.tertiarycourses.com.sg/blog/hydroponics-jar-of-water-windowsill-singapore-july-2025">hydroponics in a jam jar</a>, <a href="https://www.tertiarycourses.com.sg/blog/hydroponics-kit-practical-build-singapore-december-2025">building a deep water culture kit</a>, <a href="https://www.tertiarycourses.com.sg/blog/hydroponics-commercial-farm-visit-singapore-february-2020">inside a working hydroponic farm</a>, and <a href="https://www.tertiarycourses.com.sg/blog/hydroponics-grow-melons-singapore-class-october-2025">growing melons hydroponically</a>.</p>', 'Tertiary Infotech Academy', 1, '2014-03-08', 'TGS-2025053916', 'TGS-2025053916', 'Our First Hydroponics Class, 2014 | Tertiary Infotech Academy', 'In March 2014 we ran our first hydroponics class at Toh Orchid Farm with the late Dr Mallick, a pioneer of hydroponics in Singapore. What he taught that day still shapes the WSQ course, funded from $136.50 nett.', 'dr mallick hydroponics, hydroponics singapore history, toh orchid farm, first hydroponics class singapore, urban farming singapore, wsq hydroponics course, hydroponics pioneer singapore, hydroponic principle, skillsfuture urban farming', 'manual-skip', NOW(), NOW() FROM DUAL WHERE @is_sg > 0 AND NOT EXISTS (SELECT 1 FROM (SELECT `post_id` FROM `mmd_blog_post` WHERE `url_key` = 'hydroponics-first-class-2014-dr-mallick') x);

-- Tags (core Magento tag vocabulary; status 1 = approved)
INSERT INTO `tag` (`name`, `status`) SELECT 'Urban Farming', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Urban Farming') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'Hydroponics', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Hydroponics') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'Sustainability', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'Sustainability') x);
INSERT INTO `tag` (`name`, `status`) SELECT 'WSQ', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM (SELECT `tag_id` FROM `tag` WHERE `name` = 'WSQ') x);

SET @post_id := (SELECT `post_id` FROM `mmd_blog_post` WHERE `url_key` = 'hydroponics-first-class-2014-dr-mallick');

INSERT IGNORE INTO `mmd_blog_post_tag` (`post_id`, `tag_id`) SELECT @post_id, `tag_id` FROM `tag` WHERE @post_id IS NOT NULL AND `name` IN ('Urban Farming', 'Hydroponics', 'Sustainability', 'WSQ');

-- Seed the like count (same `likes < 100` guard as the sibling posts).
UPDATE `mmd_blog_post` SET `likes` = 121 WHERE `url_key` = 'hydroponics-first-class-2014-dr-mallick' AND `likes` < 100;
